#!/usr/bin/env python3
"""Build the reviewed federal-compute map and exportable provider table."""
import csv
import html
import json
from pathlib import Path
from build_compute_resources import standalone

ROOT=Path(__file__).resolve().parent.parent
DEST=ROOT/'docs/education-compute'
esc=html.escape

def gap_content(data):
    return '<div class="fed-gaps">'+''.join('<article><h3>'+esc(g['title'])+'</h3><p>'+esc(g['body'])+'</p></article>' for g in data['federal_platform_gaps'])+'</div>'

def summary_content(data):
    return '<p>NSF, DOE, NASA and NIH support different parts of the ecosystem. Federal development support, active operating funding, institutional subsidy and approved no-cost access are separate facts.</p><p><a href="federal-compute.html">Open the interactive map of '+str(len(data['federal_platform_map']))+' platform/service/funding families ↗</a> · <a href="federal-compute.csv" download>Download comparison table</a></p><p><strong>IDSS:</strong> NSF’s July 2026 announcement names MESA, NDP, FabAID, iDLab, BRIDGE and NSDF. These connect data/workflows with computing; they are not six equivalent GPU pools. <a href="#fedidss">Evidence</a>.</p>'+gap_content(data)+'<p><strong>UArizona finding:</strong> CyVerse publishes free Pro eligibility for UArizona users through state TRIF funding, after its core NSF awards ended in 2024. This is a practical local route to verify, with its own quotas and GPU/classroom conditions. <a href="#fedcyverse">Evidence</a>.</p>'

CSS='''
.fed-intro{font-size:20px;max-width:76ch}.fed-map{margin:28px 0;padding:24px;background:#202938;color:#fff;border-radius:14px}.fed-map h2{font-size:28px;margin:0 0 18px}.fed-map>p{font-size:14px;color:#d2dce9}.fed-layers{display:grid;grid-template-columns:1fr 1fr;gap:16px}.fed-layers article{border:1px solid #8f9cab;padding:18px;border-radius:8px;min-width:0}.fed-layers h3{font-size:23px;margin:0 0 10px;color:#f0c86b}.fed-layers p{font-size:16px;margin:0}.fed-layers .wide{grid-column:1/-1;background:#ffffff08}.fed-controls{position:sticky;top:0;z-index:2;background:#f3eddf;padding:16px 0;border-bottom:1px solid #c5c3ba}.fed-filters{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}.fed-filters button{font:inherit;font-size:14px;border:1px solid #8e949e;padding:8px 12px;background:transparent;border-radius:5px;cursor:pointer}.fed-filters button[aria-pressed=true]{background:#202938;color:#fff}.fed-controls label{font-weight:650}.fed-controls input{font:inherit;padding:10px;border:1px solid #8e949e;display:block;width:min(100%,550px);margin-top:7px;background:#fffcf5}.fed-count{font-size:14px;margin:10px 0}.fed-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;margin-top:24px}.fed-card{border:1px solid #c5c3ba;border-radius:10px;padding:22px;background:#fffcf5;min-width:0}.fed-card[hidden]{display:none}.fed-card h2{font-size:25px;line-height:1.2;margin:10px 0 16px}.fed-card h3{font-size:16px;margin:15px 0 4px}.fed-card p{font-size:15px;margin:7px 0}.fed-kind{font-size:12px!important;text-transform:uppercase;color:#2852a0;letter-spacing:.07em}.fed-status{color:#7b4921;font-weight:600}.fed-boundary{border-top:1px solid #d4d0c5;padding-top:12px}.fed-refs{font-size:12px!important;overflow-wrap:anywhere}.fed-gaps{display:grid;grid-template-columns:1fr 1fr;gap:18px}.fed-gaps article{padding:18px;border-top:3px solid #2852a0;background:#fffcf5}.fed-gaps h3{font-size:21px;margin:0 0 10px}.fed-gaps p{font-size:16px;margin:0}.fed-method{padding:20px;border-left:4px solid #2852a0;margin:30px 0}.fed-method p{font-size:15px}a,input,button{scroll-margin-top:170px}:focus-visible{outline:3px solid #b26722;outline-offset:4px}@media(max-width:700px){.fed-grid,.fed-gaps,.fed-layers{grid-template-columns:1fr}.fed-layers .wide{grid-column:auto}.fed-map{padding:18px}.fed-controls{position:relative}.fed-filters button{font-size:13px}.fed-card{padding:20px}}@media print{.fed-controls{display:none}.fed-grid,.fed-gaps,.fed-layers{display:block}.fed-card,.fed-gaps article{break-inside:avoid;margin-bottom:14px}.fed-map{background:white;color:black}.fed-map h3{color:black}.fed-map article{margin-bottom:12px}.fed-map>p{color:black}}
'''

def build():
    data=json.loads((DEST/'evidence.json').read_text())
    rows=data['federal_platform_map']; evidence=data['evidence']
    cards=[]
    for r in rows:
        refs=' · '.join('<a href="evidence.html#'+esc(k)+'">'+esc(evidence[k]['title'])+'</a>' for k in r['sources'])
        searchable=' '.join(str(v) for v in r.values()).lower()
        cards.append('<article class="fed-card" id="platform-'+esc(r['id'])+'" data-capabilities="'+esc(' '.join(r['capabilities']))+'" data-search="'+esc(searchable,quote=True)+'"><p class="fed-kind">'+esc(r['kind'])+'</p><h2>'+esc(r['name'])+'</h2><p class="fed-status">'+esc(r['status'])+'</p><p><strong>Funding:</strong> '+esc(r['funding'])+'</p>'+('<p><strong>Relationship:</strong> '+esc(r['parent'])+'</p>' if r['parent'] else '')+'<h3>Entry route</h3><p>'+esc(r['route'])+'</p><h3>Useful for</h3><p>'+esc(r['fit'])+'</p><p class="fed-boundary"><strong>Boundary:</strong> '+esc(r['boundary'])+'</p><p class="fed-refs">'+refs+'</p></article>')
    controls=''.join('<button type="button" data-fed-filter="'+key+'" aria-pressed="'+str(key=='all').lower()+'">'+label+'</button>' for key,label in [('all','All'),('teach','Teach a course'),('batch','Many independent jobs'),('train','Train models'),('api','Use a model API'),('cloud','Cloud / systems'),('data','Data and workflows'),('storage','Store / share data'),('fund','Fund local capability')])
    content='''<p class="fed-intro">A route map for research and instruction—not a promise of unlimited free accounts. Checked October 12, 2026. Select a task to compare resources, interfaces and funding pathways.</p>
<p><a href="federal-compute.csv" download>Download the comparison CSV</a> · <a href="federal-compute.json" download>Download structured map</a> · <a href="research-and-sources.txt">Full research report</a></p>
<div class="fed-map" role="figure" aria-label="Conceptual map of federal support, resource access, applications, data services and local stewardship"><h2>Public investment becomes usable computing through several layers</h2><div class="fed-layers"><article class="wide"><h3>Funding and partnerships ↓</h3><p>NSF • DOE • NASA • NIH + institutions, state partners, contributors and subscriptions</p></article><article><h3>Request and run</h3><p>ACCESS / NAIRR • OSG OSPool / PATh • NRP • mission-specific facilities</p></article><article><h3>Connect data and workflows ↔</h3><p>IDSS: MESA • NDP • FabAID • iDLab • BRIDGE • NSDF</p></article><article><h3>Deliver applications ↓</h3><p>CloudBank Classroom • Jetstream2 • NRP hubs/APIs • CyVerse apps • gateways</p></article><article><h3>Store and move data ↔</h3><p>OSN • OSDF / Pelican • Globus • institutional storage and archives</p></article><article class="wide"><h3>Operate, teach and preserve</h3><p>Local service owners • instructor/TA support • identity • workflow tools • independent backups • Libraries stewardship</p></article></div><p>Conceptual relationships, not a network measurement. Providers/services overlap: Jetstream2 is accessed through ACCESS; Nautilus is NRP’s cluster; OSPool and OSDF are different OSG services. Do not sum these names as independent capacities.</p></div>
<section><h2>What the existing plan was missing</h2>'''+gap_content(data)+'''</section>
<div class="fed-method"><p><strong>UArizona shortlist (assessment):</strong> begin with managed teaching access through Jetstream2, CloudBank Classroom or NRP; verify the state-funded CyVerse Pro benefit; use OSPool/PATh for independent batch workloads; use MESA and other IDSS projects for metadata, data discovery and reproducible workflows. Request/confirm the appropriate access before course adoption.</p><p><strong>Important funding distinctions:</strong> CyVerse’s core NSF awards ended in 2024, while UArizona Pro eligibility is supported by state TRIF. CILogon’s federally supported development transitioned to subscription-funded operations. NSF AI Infrastructure Hubs fund coordination, people and education; partners must fund compute infrastructure. IDSS awards fund service builders, not a generic instructor GPU quota.</p><p><strong>Missing operating product:</strong> a college-supported teaching service that combines a funded resource, reproducible environment, class roster/login, grading/export workflow, support owner, measured capacity and a tested restore. The proposal remains to pilot two courses, measure actual load, and scale only after those requirements are met.</p></div>
<div class="fed-controls"><label for="fedSearch">Find a platform, product, funder or task</label><input id="fedSearch" type="search" placeholder="For example: MESA, notebooks, storage, DOE"><div class="fed-filters" role="group" aria-label="Filter by task">'''+controls+'''</div><p class="fed-count" id="fedCount" aria-live="polite"></p></div><section class="fed-grid" id="fedCards" aria-label="Platform and service comparisons">'''+''.join(cards)+'''</section>
<div class="fed-method"><h2>Evidence and review limits</h2><p>Selected map of '''+str(len(rows))+''' platform/service/funding families, with six named IDSS projects and eight missing categories. Sources are federal agency and provider/project documents. 34 Exa discovery queries requested 179 result slots across six research areas; these are not 179 independently verified sources. Forty-two source records were added to the report, with targeted live checks for core claims. Earlier commercial-platform records were not all reverified.</p><p>Funding does not prove user cost, current account entitlement, production maturity, perpetual operation or an open grant deadline. No accounts, allocations, model API calls, cloud charges or grant applications were created. MESA findings use public documentation; no internal proposal or personnel plan was published.</p></div>
<script>const cards=[...document.querySelectorAll('.fed-card')];const buttons=[...document.querySelectorAll('[data-fed-filter]')];const search=document.getElementById('fedSearch');let task='all';function filter(){const q=search.value.trim().toLowerCase();let shown=0;cards.forEach(card=>{const visible=(task==='all'||card.dataset.capabilities.split(' ').includes(task))&&card.dataset.search.includes(q);card.hidden=!visible;if(visible)shown++});document.getElementById('fedCount').textContent=shown+' of '+cards.length+' families shown';buttons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.fedFilter===task)))}buttons.forEach(b=>b.onclick=()=>{task=b.dataset.fedFilter;filter()});search.addEventListener('input',filter);addEventListener('beforeprint',()=>cards.forEach(c=>c.hidden=false));addEventListener('afterprint',filter);filter()</script>'''
    (DEST/'federal-compute.html').write_text(standalone('Federally supported computing: a practical map',content,CSS).replace('href="index.html#3"','href="index.html#4"'))
    (DEST/'federal-compute.json').write_text(json.dumps(dict(checked_at='2026-10-12',platforms=rows,gaps=data['federal_platform_gaps'],research=data['federal_extension']),ensure_ascii=False,indent=2)+'\n')
    with (DEST/'federal-compute.csv').open('w',newline='') as f:
        fields=['name','category','kind','funding','status','parent','route','fit','boundary','capabilities','source_urls']
        writer=csv.DictWriter(f,fieldnames=fields);writer.writeheader()
        for r in rows:
            row={k:r[k] for k in fields if k not in ['capabilities','source_urls']};row['capabilities']='; '.join(r['capabilities']);row['source_urls']='; '.join(evidence[k]['url'] for k in r['sources']);writer.writerow(row)
    source=ROOT/'education-compute.html';text=source.read_text()
    target='<button class="repo-plan-button" id="repoPlanBtn">Repository continuity plan ↗</button>'
    if 'id="federalMapLink"' not in text:
        if target not in text:
            # Preserve the existing button label and find its exact closing tag.
            import re
            text,n=re.subn(r'(<button[^>]*id="repoPlanBtn"[^>]*>.*?</button>)',lambda m:m[1]+'<a class="repo-plan-button" id="federalMapLink" href="federal-compute.html" target="_blank" rel="noopener noreferrer">Federal compute map ↗</a>',text,count=1)
            assert n==1,'Could not find solution-slide link position'
        else:text=text.replace(target,target+'<a class="repo-plan-button" id="federalMapLink" href="federal-compute.html" target="_blank" rel="noopener noreferrer">Federal compute map ↗</a>',1)
        source.write_text(text)
    print(f'Built federal map with {len(rows)} families')

if __name__=='__main__':build()
